import{_ as i,o as t,c as a,a2 as n}from"./chunks/framework.DGvnA5EY.js";const o="/workbuddy-guide/assets/01-external-api-plug.HM1Ba1hD.png",g=JSON.parse('{"title":"第 9 章 如何接入外部 API","description":"> 内容来源：WorkBuddy 官方文档 · 连接器 / MCP（非官方整理，© 本指南作者，保留所有权利） 第 7 章你已经会装现成的连接器——QQ 邮箱、腾讯文档，点几下就能用。但现实里总有一些\\"装不到\\"的服务：公司内部的知识库、自己写的小工具、某个小众平台。","frontmatter":{"title":"第 9 章 如何接入外部 API"},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 9 章 如何接入外部 API/index.md","filePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 9 章 如何接入外部 API/index.md","lastUpdated":1791629861000}'),e={name:"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 9 章 如何接入外部 API/index.md"};function l(p,s,r,h,d,k){return t(),a("div",null,[...s[0]||(s[0]=[n('<h1 id="第-9-章-如何接入外部-api" tabindex="-1">第 9 章 如何接入外部 API <a class="header-anchor" href="#第-9-章-如何接入外部-api" aria-label="Permalink to &quot;第 9 章 如何接入外部 API&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方文档 · 连接器 / MCP（非官方整理，© 本指南作者，保留所有权利）</p></blockquote><p>第 7 章你已经会装现成的连接器——QQ 邮箱、腾讯文档，点几下就能用。但现实里总有一些&quot;装不到&quot;的服务：公司内部的知识库、自己写的小工具、某个小众平台。</p><p>这一章教你把<strong>任何</strong>服务接进 WorkBuddy。听起来像程序员的事，其实你只需要会<strong>抄一段配置、存到指定位置、点一下信任</strong>，三步完事。</p><h2 id="一、先想明白-为什么要-接" tabindex="-1">一、先想明白：为什么要&quot;接&quot; <a class="header-anchor" href="#一、先想明白-为什么要-接" aria-label="Permalink to &quot;一、先想明白：为什么要&quot;接&quot;&quot;">​</a></h2><p>打个比方：WorkBuddy 会说&quot;AI 语言&quot;，第三方服务只认&quot;API 语言&quot;（一套固定的请求规则）。</p><p>两者对不上话，就需要一个<strong>转接头</strong>。</p><ul><li>装现成连接器 = 买一个出厂配好的转接头；</li><li>自定义连接器 = 按说明书画一个自己的转接头。</li></ul><p>这个&quot;转接头&quot;的技术名字叫 <strong>MCP</strong>（Model Context Protocol，模型上下文协议）——你不用记全称，只要知道：<strong>它是 AI 和外部工具之间的通用插头标准</strong>。服务只要按这个标准做插头，WorkBuddy 就能插上就用。</p><p><img src="'+o+`" alt="小黑拿着 MCP 插头，准备插向工作台" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解 MCP 的&quot;转接头&quot;角色，与实际软件界面无关。</em></p><h2 id="二、接入方式-两条路-小白走第一条" tabindex="-1">二、接入方式：两条路，小白走第一条 <a class="header-anchor" href="#二、接入方式-两条路-小白走第一条" aria-label="Permalink to &quot;二、接入方式：两条路，小白走第一条&quot;">​</a></h2><p>官方给两种方案：</p><table tabindex="0"><thead><tr><th>方案</th><th>适用场景</th><th>小白建议</th></tr></thead><tbody><tr><td><strong>MCP + Skill</strong>（推荐）</td><td>有 API 服务，或能找到现成 MCP Server</td><td>就走这条</td></tr><tr><td>CLI + Skill</td><td>已有成熟的命令行工具</td><td>先不管，需要时再看</td></tr></tbody></table><p>一句话：<strong>服务能通过网络访问就用 MCP</strong>；CLI 方案等哪天你真的用上了再说。</p><p>MCP 服务又分两种形态：</p><ul><li><strong>远程</strong>：服务跑在某个网址上（大多数第三方 API 是这种）；</li><li><strong>本地</strong>：服务跑在你自己电脑上的一个程序里（公司内网工具常见）。</li></ul><h2 id="三、动手-写一段-mcp-json" tabindex="-1">三、动手：写一段 mcp.json <a class="header-anchor" href="#三、动手-写一段-mcp-json" aria-label="Permalink to &quot;三、动手：写一段 mcp.json&quot;">​</a></h2><p>WorkBuddy 的自定义连接器配置集中在一个文件里：</p><p><strong>用户级配置文件</strong>（对所有项目生效）：<code>~/.workbuddy/mcp.json</code> （Windows 下就是 <code>C:\\Users\\你的用户名\\.workbuddy\\mcp.json</code>）</p><p><strong>形态一：本地程序（stdio 模式）</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;enterprise-knowledge&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;python&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C:/path/to/knowledge_server.py&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;API_TOKEN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-api-token-here&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;企业内部知识库查询系统&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>读法：让 WorkBuddy 启动 <code>knowledge_server.py</code> 这个程序当转接头，凭据放在 <code>env</code> 环境变量里。</p><p><strong>形态二：远程服务（HTTP 模式）</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;remote-service&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://api.example.com/mcp/&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;headers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;x-api-key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sk-xxxxx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>读法：直接指向一个网址，key 放在请求头里。大多数第三方 MCP 服务给的就是这两行。</p><p><strong>没有 OAuth、只有长期 Token 怎么办？</strong> 官方支持「用户自填 Token 模式」：像上面两个例子那样，把对方发给你的 API Key 填进 <code>env</code> 或 <code>headers</code> 即可，不必走授权跳转。</p><p><strong>新手必踩的坑：密钥泄露。</strong></p><ul><li>配置里的 token 一律用<strong>占位符或环境变量</strong>，别把真实密钥硬编码后提交到代码仓库；</li><li>官方建议敏感信息走环境变量（如 <code>\${API_TOKEN}</code>），配置文件本身可以放心备份；</li><li>抄网上配置前，先看一眼它要什么权限——最小权限原则。</li></ul><h2 id="四、信任与启用" tabindex="-1">四、信任与启用 <a class="header-anchor" href="#四、信任与启用" aria-label="Permalink to &quot;四、信任与启用&quot;">​</a></h2><p>配置写好、文件保存后，回到 WorkBuddy：</p><ol><li>打开<strong>连接器管理</strong>；</li><li>找到新添加的连接器；</li><li>点**「信任」**——这是安全机制：新装的服务必须你亲自点头才生效；</li><li>打开开关<strong>启用</strong>。</li></ol><p>这一步和第 7 章装现成连接器完全一样，只是来源从&quot;官方市场&quot;换成了&quot;你自己的配置&quot;。</p><h2 id="五、验证-说一句话试试" tabindex="-1">五、验证：说一句话试试 <a class="header-anchor" href="#五、验证-说一句话试试" aria-label="Permalink to &quot;五、验证：说一句话试试&quot;">​</a></h2><p>在对话框直接说：</p><blockquote><p>帮我查一下企业知识库里关于「XX 项目」的文档</p></blockquote><p>如果 WorkBuddy 调用了你配置的服务并返回结果，接入成功。没反应的话，按顺序查三处：JSON 有没有多逗少逗、路径对不对、信任开关开了没有。</p><h2 id="本章任务清单" tabindex="-1">本章任务清单 <a class="header-anchor" href="#本章任务清单" aria-label="Permalink to &quot;本章任务清单&quot;">​</a></h2><ul><li>[ ] 想清楚要接什么服务（公司内部工具 / 第三方 API / 自己的小工具）</li><li>[ ] 打开（或新建）<code>~/.workbuddy/mcp.json</code>，抄入一段最小配置</li><li>[ ] 在连接器管理里完成「信任 → 启用」</li><li>[ ] 用一句自然语言验证调用成功</li><li>[ ] 检查配置里没有明文真实密钥</li></ul><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p><strong>API</strong>：程序之间互相调用数据的固定接口，像餐厅的点菜窗口——按规矩下单就能拿到菜。</p><p><strong>MCP</strong>：Model Context Protocol 的缩写，AI 和外部工具之间的&quot;通用插头标准&quot;。</p><p><strong>MCP Server</strong>：提供能力的那一端服务，可以是远程网址，也可以是你电脑上的一个程序。</p><p><strong>stdio / HTTP</strong>：两种连接形态。stdio = 启动本地程序来通信；HTTP = 访问一个网址。</p><p><strong>Token / API Key</strong>：访问服务的钥匙，一串字符。泄露了别人就能冒充你，所以要放进环境变量。</p><p><strong>环境变量</strong>：操作系统层面的&quot;隐藏小本子&quot;，程序运行时才去读，避免把密钥写死在文件里。</p></blockquote><hr><p><em>下一篇：第 10 章 自动化任务——让 WorkBuddy 自己上闹钟，到点自动干活。</em></p><p><em>本指南为第三方非官方整理，版权归作者所有，转载请注明出处。</em></p>`,44)])])}const E=i(e,[["render",l]]);export{g as __pageData,E as default};
